async function api(path,data,headers={}){const raw=data instanceof ArrayBuffer;for(let attempt=0;attempt<2;attempt++){let response;try{response=await fetch(path,{method:'POST',headers:{'X-App-Token':state.token,'Content-Type':raw?'application/octet-stream':'application/json',...headers},body:raw?data:JSON.stringify(data)});}catch{throw Error(path==='/api/login'?'Não foi possível conectar para entrar. Aguarde alguns instantes e tente novamente.':'A conexão foi interrompida. Confira a lista antes de tentar salvar novamente.');}let result;try{result=await response.json();}catch{throw Error('O servidor não respondeu corretamente. Toque em Tentar novamente para reconectar.');}if(response.status===403&&result.error==='Atualize a página para continuar.'&&attempt===0){await refreshAccess();continue;}if(response.status===401){requireSignIn('Sua sessão terminou. Entre novamente para continuar.');throw Error('Sua sessão terminou. Entre novamente para continuar.');}if(!response.ok)throw Error(result.error||'Não foi possível salvar.');return result;}}

function parseMoney(value){let text=String(value).replace(/R\$|\s/g,'');if(text.includes(','))text=text.replace(/\./g,'').replace(',','.');else if(/^\d{1,3}(\.\d{3})+$/.test(text))text=text.replace(/\./g,'');if(!/^-?\d+(\.\d{1,2})?$/.test(text))throw Error('Informe um valor com até duas casas decimais.');const negative=text.startsWith('-'),parts=text.replace('-','').split('.');const amount=Number(parts[0])*100+Number((parts[1]||'').padEnd(2,'0'));if(!Number.isSafeInteger(amount))throw Error('Valor fora do limite.');return negative?-amount:amount;}
// Money inputs use the two rightmost digits as cents; no floating point parsing.
function moneyDigits(raw){const text=String(raw),negative=text.trim().startsWith('-'),digits=text.replace(/\D/g,'');if(!digits)return negative?'-':'';const padded=(digits.replace(/^0+(?=\d)/,'')||'0').padStart(3,'0'),whole=padded.slice(0,-2).replace(/\B(?=(\d{3})+(?!\d))/g,'.');return (negative?'-':'')+whole+','+padded.slice(-2);}
function maskMoneyInput(input){const raw=input.value,caret=input.selectionStart??raw.length,rightDigits=raw.slice(caret).replace(/\D/g,'').length;input.value=moneyDigits(raw);let position=input.value.length,remaining=rightDigits;while(position>0&&remaining){position--;if(/\d/.test(input.value[position]))remaining--;}if(caret===0)position=0;input.setSelectionRange(position,position);}
function bindMoneyInputs(){const isMoney=target=>target instanceof HTMLInputElement&&target.matches('[inputmode="decimal"]');document.querySelectorAll('input[inputmode="decimal"]').forEach(input=>{input.title='Digite apenas os números: 123456 vira 1.234,56';});
 document.addEventListener('input',event=>{if(isMoney(event.target)&&!event.isComposing)maskMoneyInput(event.target);},true);
 document.addEventListener('compositionend',event=>{if(isMoney(event.target))maskMoneyInput(event.target);},true);
 document.addEventListener('beforeinput',event=>{const input=event.target;if(!isMoney(input)||input.selectionStart!==input.selectionEnd)return;const pos=input.selectionStart;if(event.inputType==='deleteContentBackward'&&pos>1&&/[.,]/.test(input.value[pos-1]))input.setSelectionRange(pos-2,pos);if(event.inputType==='deleteContentForward'&&/[.,]/.test(input.value[pos]||''))input.setSelectionRange(pos,pos+2);},true);
 document.addEventListener('paste',event=>{const input=event.target;if(!isMoney(input))return;const pasted=event.clipboardData?.getData('text');if(!pasted)return;const text=pasted.replace(/R\$/gi,'').trim();event.preventDefault();if(!/^-?\s*\d[\d.,\s]*$/.test(text)){notify('Cole apenas um valor monetário.',true);return;}let formatted;try{formatted=/[.,]/.test(text)?decimal(parseMoney(text)):moneyDigits(text);}catch{notify('Confira o valor colado. Use um valor com até duas casas decimais.',true);return;}input.setRangeText(formatted,input.selectionStart??0,input.selectionEnd??input.value.length,'end');input.dispatchEvent(new Event('input',{bubbles:true}));},true);
 document.addEventListener('focusout',event=>{const input=event.target;if(isMoney(input)&&input.value&&input.value!=='-')input.value=moneyDigits(input.value);},true);
}
function options(select,items,value){const previous=value===undefined?select.value:value;select.replaceChildren();for(const item of items){const option=el('option',item.name);option.value=item.id;select.append(option);}if([...select.options].some(o=>o.value===previous))select.value=previous;}
