function categories(extra){return [...new Set([...(state.categories||[]),'Moradia','Educação','Impostos','Seguros','Contas da casa','Salário','Outras receitas',...(state.recurring_rules||[]).map(r=>r.category),...(state.finance?.rows||[]).map(r=>r.category),...(extra?[extra]:[])])];}
function empty(parent,title,description,action){const box=el('div',null,'empty');box.append(el('h3',title),el('p',description));if(action){const button=el('button',action.label);button.onclick=action.fn;box.append(button);}parent.append(box);}
function showPage(page){if(!Object.hasOwn(PAGES,page))return;const changed=activePage!==page;activePage=page;if(location.hash!=='#'+page)history[location.hash?'pushState':'replaceState'](null,'','#'+page);document.title=PAGES[page][0]+' · Clareza';document.querySelectorAll('nav [data-page]').forEach(b=>{if(b.dataset.page===page)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});if(changed)window.scrollTo({top:0,behavior:'instant'});document.querySelectorAll('.page').forEach(n=>n.hidden=n.id!=='page-'+page);document.querySelectorAll('nav [data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));const [title,eyebrow,description]=PAGES[page];$('page-title').textContent=title;$('page-eyebrow').textContent=eyebrow;$('page-description').textContent=description;$('breadcrumb').textContent='Meu espaço / '+title;hideDashboardTooltip();if(changed)$('page-title').focus({preventScroll:true});}
function openDialog(id){document.querySelectorAll('[data-dialog-error]').forEach(n=>n.remove());document.querySelectorAll('dialog[open]').forEach(d=>d.close());$(id).showModal();}
function addMonth(month,offset){const d=new Date(+month.slice(0,4),+month.slice(5)-1+offset,1);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0');}
function line(parent,label,amount,note,total=false){const row=el('div',null,'flow-row'+(total?' total':'')),left=el('div',label);if(note)left.append(el('div',note,'muted'));row.append(left,el('strong',money(amount)));parent.append(row);return row;}
function metric(parent,label,value,note,icon){const card=el('article',null,'metric'),heading=el('div',null,'label');heading.append(el('span',label),el('span',icon||'↗','metric-icon'));card.append(heading,el('strong',money(value)),el('small',note));parent.append(card);}
