function sourceName(row){return row.source||state.cards.find(c=>c.id===row.card_id)?.name||state.accounts.find(a=>a.id===row.account_id)?.name||'Consolidado';}
function typeOf(rule){return rule.kind==='income'?'income':rule.schedule_type==='installment'?'installment':rule.commitment_type||(rule.category==='Assinaturas'?'subscription':'bill');}
function activeRules(type){return state.recurring_rules.filter(r=>typeOf(r)===type&&state.occurrences.some(o=>o.rule_id===r.id)).sort((a,b)=>{const amount=r=>state.occurrences.find(o=>o.rule_id===r.id)?.amount_cents||r.amount_cents;return amount(b)-amount(a);});}
let accessRefreshPromise=null,lastAccessCheck=0;
function connectionNotice(message,busy=false){const panel=$('connection-panel');if(panel){panel.hidden=!message;$('connection-message').textContent=message||'';$('connection-retry').disabled=busy;}if(message&&!$('auth-screen').hidden)$('auth-status').textContent=message;}
async function fetchAccessState(){const url='/api/state?month='+encodeURIComponent($('period').value);const timer=setTimeout(()=>connectionNotice('Conectando ao Clareza. A primeira abertura pode levar alguns instantes.',true),3500);try{for(let attempt=0;attempt<2;attempt++){const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),45000);try{const response=await fetch(url,{cache:'no-store',signal:controller.signal});if([502,503,504].includes(response.status)&&attempt===0){connectionNotice('O servidor está iniciando. Reconectando…',true);await new Promise(resolve=>setTimeout(resolve,1200));continue;}let result;try{result=await response.json();}catch{throw Error('O servidor ainda não está disponível. Toque em Tentar novamente.');}if(!response.ok)throw Error(result.error||'Não foi possível carregar os dados.');connectionNotice('');lastAccessCheck=Date.now();return result;}catch(error){if(attempt===0&&(error.name==='AbortError'||error instanceof TypeError)){connectionNotice('A conexão está demorando. Tentando novamente…',true);continue;}throw error;}finally{clearTimeout(timeout);}}}catch(error){const message=error.name==='AbortError'||error instanceof TypeError?'Não foi possível conectar ao Clareza. Confira sua internet e toque em Tentar novamente.':error.message;connectionNotice(message);throw Error(message);}finally{clearTimeout(timer);}}
function requireSignIn(message,token){if(token)state.token=token;state.authenticated=false;document.querySelectorAll('dialog[open]').forEach(dialog=>dialog.close());$('app-shell').hidden=true;$('auth-screen').hidden=false;hideDashboardTooltip();$('auth-status').textContent=message;}
async function refreshAccess(){if(accessRefreshPromise)return accessRefreshPromise;accessRefreshPromise=(async()=>{const result=await fetchAccessState();if(!result.authenticated){requireSignIn(state.authenticated?'Sua sessão terminou. Entre novamente para continuar.':'Entre na sua conta para continuar.',result.token);}else if(!state.authenticated||state.email!==result.email){await load();}else{state.token=result.token;}})();try{return await accessRefreshPromise;}finally{accessRefreshPromise=null;}}
function bindAccessRecovery(){$('connection-retry')?.addEventListener('click',()=>act(load,$('connection-retry')));window.addEventListener('pageshow',event=>{if(event.persisted)act(refreshAccess);});document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&lastAccessCheck&&Date.now()-lastAccessCheck>15000)act(refreshAccess);});window.addEventListener('online',()=>act(refreshAccess));}
async function load(){const sequence=++loadingSequence;$('loading').hidden=false;try{const result=await fetchAccessState();if(sequence!==loadingSequence)return;state={cards:[],imports:[],entries:[],budgets:[],cash_items:[],accounts:[],recurring_rules:[],recurrence_states:[],card_events:[],entry_matches:[],occurrences:[],horizon:[],...result};$('auth-screen').hidden=!!state.authenticated;$('app-shell').hidden=!state.authenticated;$('auth-status').textContent='';if(!state.authenticated)return;if(!state.finance)throw Error('Esta página precisa da versão atualizada do servidor. Atualize o app.');$('user-email').textContent=state.email;$('user-email').title=state.email;showPage(activePage);render();}finally{if(sequence===loadingSequence)$('loading').hidden=true;}}
function render(){renderDashboard();renderIncome();renderCommitments();renderBudget();renderChatSummary();renderRecentExpenses();$('attached-workbook').hidden=!state.has_initial_workbook;$('opening-form').elements.opening.value=decimal(state.planning.opening_cents);renderAccounts();}
let dashboardTooltipAnchor=null,dashboardTooltipTimer=null,dashboardTooltipDismissed=null;
function hideDashboardTooltip(){clearTimeout(dashboardTooltipTimer);const box=$('dashboard-tooltip');if(box)box.hidden=true;if(dashboardTooltipAnchor)dashboardTooltipAnchor.removeAttribute('aria-describedby');dashboardTooltipAnchor=null;}
function scheduleTooltipHide(){clearTimeout(dashboardTooltipTimer);dashboardTooltipTimer=setTimeout(hideDashboardTooltip,160);}
function dashboardTooltip(){let box=$('dashboard-tooltip');if(!box){box=el('div',null,'dashboard-tooltip');box.id='dashboard-tooltip';box.role='tooltip';box.hidden=true;document.body.append(box);box.onpointerenter=()=>clearTimeout(dashboardTooltipTimer);box.onpointerleave=scheduleTooltipHide;}return box;}
function positionDashboardTooltip(){if(!dashboardTooltipAnchor)return;const box=dashboardTooltip(),anchor=dashboardTooltipAnchor.getBoundingClientRect(),width=box.offsetWidth,height=box.offsetHeight,gap=10;let left=Math.min(Math.max(10,anchor.left+anchor.width/2-width/2),window.innerWidth-width-10),top=anchor.bottom+gap;if(top+height>window.innerHeight-10)top=Math.max(10,anchor.top-height-gap);box.style.left=left+'px';box.style.top=top+'px';}
function showDashboardTooltip(anchor){if(dashboardTooltipDismissed===anchor)return;clearTimeout(dashboardTooltipTimer);if(dashboardTooltipAnchor&&dashboardTooltipAnchor!==anchor)dashboardTooltipAnchor.removeAttribute('aria-describedby');dashboardTooltipAnchor=anchor;const data=anchor._dashboardDetails,box=dashboardTooltip();box.replaceChildren(el('strong',data.title,'tooltip-title'),el('p',data.note,'tooltip-note'));if(data.rows?.length){const list=el('div',null,'tooltip-items');for(const row of data.rows){const item=el('div',null,'tooltip-item');item.append(el('span',row.label),el('b',typeof row.value==='number'?money(row.value):row.value));list.append(item);}box.append(list);}if(data.total!==undefined){const total=el('div',null,'tooltip-total');total.append(el('span',data.totalLabel||'Total'),el('b',money(data.total)));box.append(total);}box.hidden=false;anchor.setAttribute('aria-describedby',box.id);positionDashboardTooltip();}
function explainDashboardValue(node,details){node._dashboardDetails=details;node.classList.add('has-dashboard-details');node.setAttribute('tabindex','0');node.setAttribute('role','button');node.setAttribute('aria-label','Detalhes: '+details.title);node.onpointerenter=event=>{if(event.pointerType!=='touch')showDashboardTooltip(node);};node.onpointerleave=()=>{if(dashboardTooltipDismissed===node)dashboardTooltipDismissed=null;scheduleTooltipHide();};node.onfocus=()=>showDashboardTooltip(node);node.onblur=()=>{dashboardTooltipDismissed=null;hideDashboardTooltip();};node.onclick=event=>{event.stopPropagation();if(dashboardTooltipAnchor===node&&!dashboardTooltip().hidden&&event.detail===0)return;showDashboardTooltip(node);};node.onkeydown=event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();dashboardTooltipDismissed=null;showDashboardTooltip(node);}};}
function dashboardBreakdown(title,rows,total,note){const ordered=rows.slice().sort((a,b)=>Math.abs(b.amount_cents)-Math.abs(a.amount_cents));const visible=ordered.slice(0,5).map(r=>({label:r.description,value:r.amount_cents}));if(ordered.length>5)visible.push({label:'Outros '+(ordered.length-5)+' lançamentos',value:ordered.slice(5).reduce((n,r)=>n+r.amount_cents,0)});return {title,note:note||monthLabel(state.finance.month)+' · '+rows.length+' lançamento'+(rows.length===1?'':'s')+'.',rows:visible,total};}
function reserveTooltip(){const p=state.planning,s=state.active_savings_schedule;return {title:'Reserva planejada',note:'O orçamento considera o maior entre a meta e o valor já separado, sem descontar os dois novamente.'+(s&&!state.savings_override?' Meta recorrente desde '+monthLabel(s.start_month)+'.':''),rows:[{label:'Meta do mês',value:p.savings_target_cents},{label:'Já separado neste mês',value:p.saved_cents}],total:state.finance.reserved_cents,totalLabel:'Considerado no orçamento'};}
function renderDashboardDetails(){hideDashboardTooltip();const f=state.finance,expenses=f.rows.filter(r=>r.kind==='expense'),incomes=f.rows.filter(r=>r.kind==='income');const available={title:'Disponível para gastar · '+monthLabel(f.month),note:f.deficit_cents?'O resultado está negativo. A tela mostra R$ 0,00 disponível; faltam '+money(f.deficit_cents)+' para cobrir o planejamento.':'Receitas menos os custos do mês e a reserva planejada. O saldo inicial das contas não entra neste cálculo.',rows:[{label:'Receitas do mês',value:f.income_cents},{label:'Custos recorrentes',value:-f.recurring_costs_cents},{label:'Variáveis e ajustes',value:-f.variable_costs_cents},{label:'Reserva planejada',value:-f.reserved_cents}],total:f.signed_remaining_cents,totalLabel:'Resultado do mês'};explainDashboardValue($('dash-available'),available);explainDashboardValue($('dash-budget-label'),{title:'Orçamento para gastos variáveis',note:'Receitas menos compromissos recorrentes e reserva, antes de subtrair os gastos variáveis já registrados.',rows:[{label:'Receitas do mês',value:f.income_cents},{label:'Compromissos recorrentes',value:-f.recurring_costs_cents},{label:'Reserva planejada',value:-f.reserved_cents}],total:f.spend_budget_cents});const recurring=dashboardBreakdown('Custos recorrentes',expenses.filter(r=>r.recurring),f.recurring_costs_cents),variable=dashboardBreakdown('Gastos variáveis e ajustes',expenses.filter(r=>!r.recurring),f.variable_costs_cents,'Gastos pontuais, créditos e ajustes de fatura em '+monthLabel(f.month)+'. Créditos diminuem o custo.');const reserve=reserveTooltip();const flows=[dashboardBreakdown('Receitas do mês',incomes,f.income_cents),recurring,variable,reserve,available];[...$('dash-flow').children].forEach((node,i)=>explainDashboardValue(node,flows[i]));const metrics=[dashboardBreakdown('Receitas recorrentes',incomes.filter(r=>r.recurring),f.recurring_income_cents),recurring,variable,reserve];[...$('dash-metrics').children].forEach((node,i)=>explainDashboardValue(node,metrics[i]));explainDashboardValue($('category-total'),dashboardBreakdown('Total dos custos',expenses,f.costs_cents));}
function bindDashboardTooltips(){document.addEventListener('keydown',event=>{if(event.key==='Escape'){dashboardTooltipDismissed=dashboardTooltipAnchor;hideDashboardTooltip();}});document.addEventListener('pointerdown',event=>{if(dashboardTooltipAnchor&&!dashboardTooltipAnchor.contains(event.target)&&!dashboardTooltip().contains(event.target))hideDashboardTooltip();});window.addEventListener('resize',hideDashboardTooltip);window.addEventListener('scroll',()=>{if(!dashboardTooltipAnchor)return;const rect=dashboardTooltipAnchor.getBoundingClientRect();if(rect.bottom<0||rect.top>innerHeight)hideDashboardTooltip();else positionDashboardTooltip();},true);}
function renderRanking(parent,rows,kind){parent.replaceChildren();if(!rows.length){empty(parent,kind==='income'?'As receitas entram aqui':'Seu mês começa com clareza',kind==='income'?'Cadastre suas fontes de renda para acompanhar a entrada de dinheiro.':'Registre os gastos e compromissos para acompanhar seus maiores custos.');return;}for(const [index,row] of rows.slice(0,5).entries()){const item=el('div',null,'rank-row'),text=el('div',null,'row-description');text.append(el('strong',row.description),el('small',row.category+' · '+(row.recurring?'Recorrente':'Pontual')));item.append(el('span',String(index+1).padStart(2,'0'),'row-icon'),text,el('span',money(row.amount_cents),'row-money'+(kind==='income'?' green':'')));explainDashboardValue(item,{title:row.description,note:monthLabel(state.finance.month),rows:[{label:'Categoria',value:row.category},{label:'Origem',value:sourceName(row)},{label:'Data',value:row.date.split('-').reverse().join('/')},{label:'Frequência',value:row.recurring?TYPES[row.type]||'Recorrente':'Pontual'}],total:row.amount_cents});parent.append(item);}}
