function prepareMobileTable(table){if(!table.tHead)return;table.classList.add('responsive-table');table.setAttribute('role','table');const headers=[...table.tHead.rows[0].cells].map(th=>th.textContent.trim());table.tHead.setAttribute('role','rowgroup');for(const row of table.tHead.rows){row.setAttribute('role','row');for(const th of row.cells){th.scope='col';th.setAttribute('role','columnheader');}}for(const body of table.tBodies){body.setAttribute('role','rowgroup');for(const [rowIndex,row]of [...body.rows].entries()){row.setAttribute('role','row');for(const [i,cell]of [...row.cells].entries()){const label=headers[i]||'Ações';cell.dataset.label=label;cell.setAttribute('role','cell');cell.classList.toggle('mobile-title-cell',i===0&&label!=='Incluir');cell.classList.toggle('mobile-actions-cell',!headers[i]);cell.classList.toggle('mobile-wide-cell',['Descrição','Compromisso','Fonte de receita','Origem','Nome na fatura','Vincular previsão','Próximos meses'].includes(label));for(const control of cell.querySelectorAll('input,select,textarea')){if(!control.hasAttribute('aria-label')&&!control.labels?.length)control.setAttribute('aria-label',label+' · lançamento '+(rowIndex+1));}}}}}
