function renderInvoiceRows(){const parent=$('invoice-rows');parent.replaceChildren();for(const row of invoicePreview.rows){if(row.include===undefined)row.include=true;const tr=el('tr');const cell=child=>{const td=el('td');td.append(child);tr.append(td);};const include=el('input');include.type='checkbox';include.checked=row.include;include.onchange=()=>{row.include=include.checked;inspectInvoice();};cell(include);for(const [key,type,value]of [['date','date',row.date],['description','text',row.description],['amount','text',decimal(row.amount)]]){const input=el(key==='description'?'textarea':'input');if(key==='description')input.rows=2;else input.type=type;if(key==='amount')input.inputMode='decimal';input.value=value;input.setAttribute('aria-label',key+' linha '+row.source_line);input.onchange=()=>{try{row[key]=key==='amount'?parseMoney(input.value):input.value;inspectInvoice();}catch(error){notify(error.message,true);if(key==='amount')input.value=decimal(row.amount);}};cell(input);}const category=el('select');options(category,categories(row.category).map(name=>({id:name,name})),row.category);category.onchange=()=>row.category=category.value;cell(category);const kind=el('select');options(kind,['compra','credito','estorno','juros','tarifa'].map(name=>({id:name,name})),row.kind);kind.onchange=()=>row.kind=kind.value;cell(kind);const part=el('input');part.value=row.current+'/'+row.total;part.onchange=()=>{const match=part.value.match(/^(\d{1,3})\/(\d{1,3})$/);if(!match||+match[1]<1||+match[1]>+match[2]||+match[2]>120){notify('Use uma parcela válida, como 2/6.',true);part.value=row.current+'/'+row.total;return;}row.current=+match[1];row.total=+match[2];};cell(part);const link=el('select');options(link,[{id:'',name:'Não vincular'},...(row.match_candidates||[]).map(c=>({id:c.type+':'+c.id,name:c.label+' · '+money(c.amount)}))],row.match_id?row.match_type+':'+row.match_id:'');const future=el('select');options(future,[{id:'',name:'Não criar previsão'},{id:'installment',name:'Parcelas restantes'},{id:'monthly',name:'Assinatura mensal'}]);if(row.future_mode===undefined&&row.total>row.current&&row.amount>0&&row.match_type!=='rule')row.future_mode='installment';future.value=row.future_mode||'';future.disabled=row.match_type==='rule'||row.amount<=0;future.onchange=()=>row.future_mode=future.value;link.onchange=()=>{const ref=link.value;row.match_type=ref?ref.split(':')[0]:null;row.match_id=ref?ref.slice(ref.indexOf(':')+1):null;future.disabled=row.match_type==='rule'||row.amount<=0;if(row.match_type==='rule'){row.future_mode='';future.value='';}};cell(link);cell(future);const details=el('details',null,'origin-details');details.append(el('summary',row.source_page?'Pág. '+row.source_page:row.manual?'Manual':'Linha '+row.source_line),el('p',row.original_text||row.description));if(row.source_card_last4)details.append(el('p','Cartão final '+row.source_card_last4));if(row.beneficiary)details.append(el('p','Beneficiário: '+row.beneficiary));for(const detail of [...(row.source_details||[]),...(row.warnings||[])])details.append(el('p',detail));cell(details);parent.append(tr);}inspectInvoice();}
async function readInvoice(event){event.preventDefault();const form=event.target,button=form.querySelector('button');await act(async()=>{const file=form.elements.file.files[0];if(!file||file.size>5000000)throw Error('Envie uma fatura de até 5 MB.');const pdf=file.name.toLowerCase().endsWith('.pdf');if(!pdf&&!file.name.toLowerCase().endsWith('.csv'))throw Error('Escolha um PDF ou CSV.');invoicePreview=null;$('invoice-review').hidden=true;button.textContent='Lendo lançamentos…';try{const result=await api(pdf?'/api/preview-pdf':'/api/preview',await file.arrayBuffer(),{'X-Card-ID':form.elements.card_id.value,'X-Invoice-Month':form.elements.month.value,'X-PDF-Password':pdf?encodeURIComponent(form.elements.password.value):''});invoicePreview={...result,card:form.elements.card_id.value,month:form.elements.month.value};if(Number.isSafeInteger(result.invoice_total_cents))form.elements.expected.value=decimal(result.invoice_total_cents);renderInvoice();notify('Fatura lida. Confira os lançamentos antes de confirmar.');}finally{button.textContent='Ler fatura';form.elements.password.value='';}},button);}
async function confirmInvoice(){const button=$('invoice-confirm');await act(async()=>{const form=$('invoice-form');if(!invoicePreview||!$('invoice-ack').checked)throw Error('Confirme a conferência da fatura.');if(invoicePreview.card!==form.elements.card_id.value||invoicePreview.month!==form.elements.month.value)throw Error('Cartão ou mês alterado. Leia o arquivo novamente.');const rows=invoicePreview.rows.filter(r=>r.include!==false);for(const row of rows)if(!row.description.trim()||!/^\d{4}-\d{2}-\d{2}$/.test(row.date))throw Error('Confira descrição e data de todas as linhas incluídas.');if(rows.reduce((n,r)=>n+r.amount,0)!==parseMoney(form.elements.expected.value))throw Error('A soma precisa coincidir com o total informado.');await api('/api/confirm',{card:invoicePreview.card,month:invoicePreview.month,digest:invoicePreview.digest,expected:form.elements.expected.value,rows:rows.map(r=>({...r,user_reviewed:true}))});$('period').value=invoicePreview.month;invoicePreview=null;$('invoice-review').hidden=true;$('data-dialog').close();await load();notify('Fatura importada. Custos e orçamento atualizados.');},button);}
function renderWorkbook(preview){workbookPreview=preview;$('workbook-review').hidden=false;const description=$('workbook-description');description.replaceChildren();description.append(el('div',preview.rows.length+' tipos de receita/custo · '+preview.months.length+' meses de planejamento','info-box'));for(const warning of preview.warnings)description.append(el('p',warning,'small muted'));options($('workbook-start'),preview.months.map(m=>({id:m,name:monthLabel(m)})));sourceOptions($('workbook-card'),state.cards,'Selecione o cartão padrão',state.cards.length===1?state.cards[0].id:'');sourceOptions($('workbook-account'),state.accounts,'Consolidado / não informado');const rows=$('workbook-rows');rows.replaceChildren();for(const item of preview.rows){const tr=el('tr');tr.dataset.id=item.id;const include=el('input');include.type='checkbox';include.checked=true;const classification=el('select');options(classification,(item.kind==='income'?['income']:['bill','subscription','installment']).map(id=>({id,name:TYPES[id]})),item.commitment_type||'bill');classification.disabled=item.kind==='income';const channel=el('select');options(channel,[{id:'cash',name:item.kind==='income'?'Receita em conta':'Conta / Pix'},{id:'card',name:'Cartão'}],item.channel);channel.disabled=item.kind==='income';const specific=el('select');const update=()=>sourceOptions(specific,channel.value==='card'?state.cards:state.accounts,'Usar padrão acima');update();channel.onchange=update;const pattern=el('textarea');pattern.rows=2;pattern.value=item.match_pattern;for(const child of [include,el('span',item.description+(item.mapping_confirmed?' · vínculo confirmado':'')),classification,channel,specific,el('span',money(item.values[$('period').value]??Object.values(item.values).find(v=>v>0)??0)),pattern]){const td=el('td');td.append(child);tr.append(td);}tr._choice={include,classification,channel,specific,pattern};rows.append(tr);}$('workbook-ack').checked=false;}
async function confirmWorkbook(){const button=$('workbook-confirm');await act(async()=>{if(!workbookPreview||!$('workbook-ack').checked)throw Error('Confirme a revisão antes de importar.');const choices=[...$('workbook-rows').children].map(tr=>({id:tr.dataset.id,skip:!tr._choice.include.checked,commitment_type:tr._choice.classification.value,channel:tr._choice.channel.value,card_id:tr._choice.channel.value==='card'?tr._choice.specific.value:null,account_id:tr._choice.channel.value==='cash'?tr._choice.specific.value:null,match_pattern:tr._choice.pattern.value}));await api('/api/workbook-confirm',{key:workbookPreview.key,start_month:$('workbook-start').value,card_id:$('workbook-card').value,account_id:$('workbook-account').value,choices,honor_status:$('workbook-status').checked,replace_targets:$('workbook-targets').checked});workbookPreview=null;$('workbook-review').hidden=true;$('data-dialog').close();await load();showPage('dashboard');notify('Planejamento importado. Revise as previsões e os vínculos com as faturas.');},button);}
let installPrompt=null;
function bindAppInstall(){const button=$('install-app'),standalone=matchMedia('(display-mode: standalone)').matches||navigator.standalone;button.hidden=!!standalone;window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;});window.addEventListener('appinstalled',()=>{installPrompt=null;button.hidden=true;});button.onclick=()=>act(async()=>{if(installPrompt){const prompt=installPrompt;installPrompt=null;await prompt.prompt();await prompt.userChoice;return;}const local=['localhost','127.0.0.1'].includes(location.hostname)||/^192\.168\.|^10\.|^172\.(1[6-9]|2\d|3[01])\./.test(location.hostname);$('install-connection-note').textContent=local?'Este endereço depende do Mac ligado e da mesma rede Wi-Fi. Adicionar o ícone não muda essa condição. Para usar fora de casa, o Clareza precisa de um endereço HTTPS permanente.':'O app precisa de conexão para consultar e salvar suas finanças. A instalação não salva gastos quando você está sem internet.';openDialog('install-dialog');},button);}
function bindEvents(){
 document.querySelectorAll('[data-page]').forEach(button=>button.onclick=()=>showPage(button.dataset.page));document.querySelectorAll('[data-close]').forEach(button=>button.onclick=()=>button.closest('dialog').close());document.querySelectorAll('dialog').forEach(dialog=>dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}}));
 $('auth-form').onsubmit=event=>{event.preventDefault();act(async()=>{const form=event.target;await api('/api/login',Object.fromEntries(new FormData(form)));form.reset();await load();notify('Bem-vindo ao Clareza.');},event.target.querySelector('.primary'));};$('signup').onclick=()=>act(async()=>{const form=$('auth-form');if(!form.reportValidity())return;const result=await api('/api/signup',Object.fromEntries(new FormData(form)));form.reset();await load();notify(result.message||'Conta criada.');},$('signup'));$('logout').onclick=()=>act(async()=>{await api('/api/logout',{});invoicePreview=null;workbookPreview=null;await load();},$('logout'));
 $('period').onchange=()=>act(load);$('previous-month').onclick=()=>{$('period').value=addMonth($('period').value,-1);act(load);};$('next-month').onclick=()=>{$('period').value=addMonth($('period').value,1);act(load);};$('quick-expense').onclick=()=>showPage('chat');$('new-income').onclick=()=>openRecord('income');$('new-commitment').onclick=()=>activeTab==='cards'?openCard():openRecord(activeTab);document.querySelectorAll('[data-tab]').forEach(button=>button.onclick=()=>{activeTab=button.dataset.tab;renderCommitments();});$('all-expenses').onclick=()=>showMovements('expense');$('manual-expense').onclick=()=>openRecord('variable');$('settings-button').onclick=() =>openData('accounts');$('settings-avatar').onclick=()=>openData('accounts');document.querySelectorAll('[data-data-tab]').forEach(button=>button.onclick=()=>openData(button.dataset.dataTab));$('import-invoice').onclick=()=>openData('invoice');$('invoice-history').onclick=showHistory;$('reconcile-button').onclick=openMatches;
 $('fixed-bill-form').onsubmit=event=>{event.preventDefault();act(async()=>{await api('/api/recurring-expense-update',Object.fromEntries(new FormData(event.target)));$('fixed-bill-dialog').close();await load();notify('Cadastro da recorrência atualizado.');},event.target.querySelector('.primary'));};
 $('record-form').onsubmit=saveRecord;const record=$('record-form');for(const name of ['mode','channel'])record.elements[name].onchange=()=>{configureRecord();suggestRecordMonth();updateRecordImpact();};record.elements.date.onchange=suggestRecordMonth;record.elements.card_id.onchange=suggestRecordMonth;record.elements.month.onchange=updateRecordImpact;$('entry-search').oninput=renderRecentExpenses;$('jump-to-records').onclick=()=>document.querySelector('.recent-expenses-card').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});
 $('card-form').onsubmit=event=>{event.preventDefault();act(async()=>{const data=Object.fromEntries(new FormData(event.target));await api(data.id?'/api/card-update':'/api/cards',data);$('card-dialog').close();await load();notify('Cartão salvo.');},event.target.querySelector('.primary'));};$('payment-form').onsubmit=event=>{event.preventDefault();act(async()=>{await api('/api/card-payment',{...Object.fromEntries(new FormData(event.target)),month:$('period').value});$('payment-dialog').close();await load();notify('Pagamento atualizado sem duplicar a despesa.');},event.target.querySelector('.primary'));};
 $('recurring-reserve-form').onsubmit=event=>{event.preventDefault();act(async()=>{await api('/api/savings-schedule',Object.fromEntries(new FormData(event.target)));await load();notify('Reserva recorrente salva para os meses seguintes.');},event.target.querySelector('button'));};$('use-recurring-reserve').onclick=()=>act(async()=>{await api('/api/savings-use-recurring',{month:$('period').value});await load();notify('Meta recorrente aplicada neste mês.');},$('use-recurring-reserve'));
 $('reserve-form').onsubmit=event=>{event.preventDefault();act(async()=>{await api('/api/month-plan',{month:$('period').value,opening:decimal(state.planning.opening_cents),savings_override:true,...Object.fromEntries(new FormData(event.target))});await load();notify('Reserva planejada atualizada.');},event.target.querySelector('.primary'));};$('apply-suggestion').onclick=()=>{$('reserve-form').elements.target.value=decimal(state.finance.suggestion.amount_cents);notify('Simulação preenchida. Salve a reserva para aplicar ao orçamento.');};$('profile-form').onsubmit=event=>{event.preventDefault();act(async()=>{const data=Object.fromEntries(new FormData(event.target));data.needs_liquidity=data.needs_liquidity==='true';await api('/api/investor-profile',data);await load();notify('Objetivo e simulação atualizados.');},event.target.querySelector('.primary'));};
 document.querySelectorAll('[data-prompt]').forEach(button=>button.onclick=()=>{$('chat-message').value=button.dataset.prompt;$('chat-message').focus();});$('chat-form').onsubmit=event=>{event.preventDefault();act(async()=>{const message=$('chat-message').value;chatBubble(message,'user');const result=await api('/api/chat-preview',{message,month:$('period').value});if(result.reply)chatBubble(result.reply,'assistant');else{chatBubble('Preparei o lançamento. Confira o valor, a origem e o mês antes de salvar.','assistant');const d=result.draft;openRecord(d.kind==='income'?'income':d.mode==='installment'?'installment':d.mode==='monthly'?'subscription':'variable',null,d);}},event.target.querySelector('button'));};
 $('invoice-form').onsubmit=readInvoice;$('invoice-form').elements.expected.oninput=()=>{if(invoicePreview)inspectInvoice();};$('invoice-ack').onchange=()=>{if(invoicePreview)inspectInvoice();};$('invoice-confirm').onclick=confirmInvoice;$('invoice-add-row').onclick=()=>{if(!invoicePreview)return;invoicePreview.rows.push({date:invoicePreview.month+'-01',description:'',amount:0,category:'Outros',kind:'compra',current:1,total:1,source_line:0,manual:true});$('invoice-ack').checked=false;renderInvoiceRows();};
 $('workbook-form').onsubmit=event=>{event.preventDefault();act(async()=>{const file=event.target.elements.file.files[0];if(!file||!file.name.toLowerCase().endsWith('.xlsx')||file.size>5000000)throw Error('Escolha uma planilha .xlsx de até 5 MB.');renderWorkbook(await api('/api/workbook-preview',await file.arrayBuffer()));},event.target.querySelector('.primary'));};$('attached-workbook').onclick=()=>act(async()=>renderWorkbook(await api('/api/workbook-attached',{})),$('attached-workbook'));$('workbook-confirm').onclick=confirmWorkbook;
 $('account-form').onsubmit=event=>{event.preventDefault();act(async()=>{await api('/api/accounts',Object.fromEntries(new FormData(event.target)));event.target.reset();await load();renderAccounts();notify('Conta cadastrada.');},event.target.querySelector('button'));};$('opening-form').onsubmit=event=>{event.preventDefault();act(async()=>{await api('/api/month-plan',{month:$('period').value,opening:event.target.elements.opening.value,target:decimal(state.planning.savings_target_cents),saved:decimal(state.planning.saved_cents)});await load();notify('Saldo inicial atualizado.');},event.target.querySelector('button'));};$('match-form').elements.source.onchange=renderMatchOptions;$('match-form').onsubmit=event=>{event.preventDefault();act(async()=>{const ref=event.target.elements.source.value;await api('/api/entry-match',{entry_id:event.target.elements.entry.value,type:ref.split(':')[0],source_id:ref.slice(ref.indexOf(':')+1),month:$('period').value});await load();openMatches();notify('Lançamento vinculado. A despesa conta uma única vez.');},event.target.querySelector('button'));};
}
